#!/usr/bin/env ruby
# frozen_string_literal: true

# Writes site/src/content/docs/reference/accuracy.md, which is the site's only
# rendering of measured accuracy (#109).
#
#     $ bundle exec rake site:accuracy
#
# `benchmark/results/accuracy.md` is regenerated by `rake benchmark:accuracy`
# and committed -- it is the number this library actually finds, measured
# against the labeled set, not a claim. This script copies it under a
# Starlight frontmatter rather than the page carrying its own prose, on the
# same rule as site/bin/generate_sources.rb: two renderings of one figure
# drift the first time the matcher is tuned, so there can only be one.
#
# The source file's own top-level heading is dropped -- Starlight renders the
# frontmatter `title` as the page's heading, and keeping both would print
# "Accuracy" twice. Everything under it is copied verbatim.
#
# The output is committed so the site builds with Node alone, and
# spec/site_accuracy_data_spec.rb regenerates it and fails if the committed
# copy has drifted from benchmark/results/accuracy.md.

module GenerateAccuracy
  ROOT = File.expand_path("../..", __dir__)
  SOURCE = File.join(ROOT, "benchmark", "results", "accuracy.md")
  OUTPUT = File.join(ROOT, "site", "src", "content", "docs", "reference", "accuracy.md")

  FRONTMATTER = <<~FRONTMATTER
    ---
    title: Accuracy
    description: Precision, recall and F1 against the labeled set, measured and committed with the code that produced them.
    sidebar:
      order: 5
    ---
  FRONTMATTER

  NOTICE = "<!-- Generated by site/bin/generate_accuracy.rb from benchmark/results/accuracy.md, " \
           "via `rake site:accuracy`. Edit that file, not this one. -->"

  module_function

  def call
    body = File.read(SOURCE).sub(/\A# .*\n\n?/, "")
    "#{FRONTMATTER}\n#{NOTICE}\n\n#{body}"
  end
end

if $PROGRAM_NAME == __FILE__
  File.write(GenerateAccuracy::OUTPUT, GenerateAccuracy.call)
  puts "wrote #{GenerateAccuracy::OUTPUT.sub("#{GenerateAccuracy::ROOT}/", "")}"
end
